'use strict';
const $=s=>document.querySelector(s);
const controls=document.querySelectorAll('[data-score]');
if(controls.length){fetch('assets/results-v2.json').then(r=>{if(!r.ok)throw new Error('results unavailable');return r.json()}).then(data=>{controls.forEach(btn=>btn.addEventListener('click',()=>{controls.forEach(b=>b.setAttribute('aria-pressed',String(b===btn)));document.querySelectorAll('.bar-row').forEach(row=>{const entry=data.scores.find(x=>x.method===row.dataset.method);if(!entry)return;const v=entry[btn.dataset.score];row.querySelector('.bar-fill').style.setProperty('--width',`${v/5*100}%`);row.querySelector('.bar-value').textContent=v.toFixed(6);});}));}).catch(()=>{controls.forEach(b=>{b.disabled=true;b.title='离线时显示已内嵌的综合成绩';});});}
const routes={heuristic:['先保证动作合法，再比较集合价值','从低成本驱逐与next保护出发，发现单个对象排序不能代替容量约束下的集合选择。最终保留top4子集规划、合法回退和冗余SPILL剪枝。','进入最终方案：有限候选与成本规划'],learning:['模型之前，先检查教师是否稳定','小树试图选择专家与动作，但150个教师状态中，44个在更换续接策略后动作排名改变。校准仍未胜过强AI参照，路线暂停，最终方案不含训练模型。','保留认识：标签、观测与长期费用必须一致'],risk:['观察访问分布，也观察自己造成的周转','next去重样本用于概率；Miss与盘上暴露用于重访反馈。我方joint改善动态数据，但未稳定通过原面板。R81保留自己的重访回退，没有整体合入joint。','保留机制：观测来源区分与重访回退'],hierarchy:['用两个时间尺度拆开响应与稳定性','R80将我方部分概率估值思路接入同学原框架；R81进一步用256半衰期估计算子份额、2048半衰期估计条件分区偏好，再结合大小和读写代价。','最终选择：R81分层热度与成本调度']};
document.querySelectorAll('[data-route]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('[data-route]').forEach(b=>{b.classList.toggle('active',b===btn);b.setAttribute('aria-pressed',String(b===btn));});const r=routes[btn.dataset.route],target=$('#route-detail');if(target){target.querySelector('h3').textContent=r[0];target.querySelector('p').textContent=r[1];target.querySelector('.pill').textContent=r[2];}}));
function drawHeat(mode){const target=$('#heat-grid');if(!target)return;const pi=mode==='shift'?[.08,.12,.65,.15]:[.65,.2,.1,.05];const conditional=mode==='operator'?Array(8).fill(1/8):[.58,.18,.08,.05,.04,.03,.025,.015];target.replaceChildren();pi.forEach((m,i)=>{const l=document.createElement('span');l.className='heat-row-label';l.textContent=`算子 ${i+1}`;target.append(l);conditional.forEach((c,j)=>{const p=m*c,cell=document.createElement('span');cell.className='heat-cell';const strength=Math.min(1,p/.377);cell.style.background=`rgb(${Math.round(231-223*strength)},${Math.round(239-113*strength)},${Math.round(225-95*strength)})`;cell.style.color=strength>.5?'#fff':'#32594b';cell.textContent=(p*100).toFixed(1);cell.title=`算子${i+1}，分区${j+1}：${(p*100).toFixed(2)}%`;target.append(cell);});});$('#heat-explain').textContent=mode==='operator'?'示意：行的总量不同，但每行内部一样；算子内没有可学习的分区差异。':mode==='partition'?'示意：算子份额不变，再给每行加入分区偏斜；现在两个层面都有可辨别的信息。':'示意：分区条件偏好不变，热点算子从1迁移到3；快算子估计负责跟随这类变化。';}
document.querySelectorAll('[data-heat]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('[data-heat]').forEach(b=>b.setAttribute('aria-pressed',String(b===btn)));drawHeat(btn.dataset.heat);}));drawHeat('operator');
const age=$('#decay-age');function decay(){if(!age)return;const q=+age.value;$('#decay-age-label').textContent=q;$('#fast-weight').textContent=(100*2**(-q/256)).toFixed(2)+'%';$('#slow-weight').textContent=(100*2**(-q/2048)).toFixed(2)+'%';const marker=$('#decay-marker');if(marker){const x=50+520*q/4096;marker.setAttribute('x1',x);marker.setAttribute('x2',x);}}
age?.addEventListener('input',decay);decay();
const op=$('#op-prob'),part=$('#part-prob'),size=$('#part-size');function recalc(){if(!op||!part||!size)return;const p=(+op.value/100)*(+part.value/100),s=+size.value*1048576,total=64*p*(s/1024+s/512+100)/1000;$('#op-label').textContent=`${op.value}%`;$('#part-label').textContent=`${part.value}%`;$('#size-label').textContent=`${size.value} MiB`;$('#joint-value').textContent=`${(p*100).toFixed(2)}%`;$('#value-total').textContent=`${total.toFixed(2)} ms`;$('#value-density').textContent=(total/(+size.value)).toFixed(2);}[op,part,size].filter(Boolean).forEach(e=>e.addEventListener('input',recalc));recalc();
if('IntersectionObserver'in window){const links=[...document.querySelectorAll('.toc a')];const observer=new IntersectionObserver(entries=>{for(const e of entries){if(e.isIntersecting)links.forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+e.target.id));}},{rootMargin:'-15% 0px -65% 0px'});document.querySelectorAll('.chapter').forEach(e=>observer.observe(e));}
